/* ETM_TRCTRACEIDR: Sets the trace ID for instruction trace. If data trace is enabled then it also sets the trace ID for data
                     trace, to (trace ID for instruction trace) + 1. This register must always be programmed as part of trace
                     unit initialization. Might ignore writes when the trace unit is enabled or not idle. */

  #define ETM_TRCTRACEIDR_ResetValue (0x00000000UL)  /*!< Reset value of TRCTRACEIDR register.                                 */

/* TRACEID @Bits 0..6 : Trace ID field. Sets the trace ID value for instruction trace. Bit[0] must be zero if data trace is
                        enabled. If data trace is enabled then a trace unit sets the trace ID for data trace, to TRACEID+1. */

  #define ETM_TRCTRACEIDR_TRACEID_Pos (0UL)          /*!< Position of TRACEID field.                                           */
  #define ETM_TRCTRACEIDR_TRACEID_Msk (0x7FUL << ETM_TRCTRACEIDR_TRACEID_Pos) /*!< Bit mask of TRACEID field.                  */


/* ETM_TRCQCTLR: Controls when Q elements are enabled. Might ignore writes when the trace unit is enabled or not idle. This
                  register must be programmed if it is implemented and TRCCONFIGR.QE is set to any value other than 0b00. */

  #define ETM_TRCQCTLR_ResetValue (0x00000000UL)     /*!< Reset value of TRCQCTLR register.                                    */

/* RANGE0 @Bit 0 : Specifies the address range comparators to be used for controlling Q elements. */
  #define ETM_TRCQCTLR_RANGE0_Pos (0UL)              /*!< Position of RANGE0 field.                                            */
  #define ETM_TRCQCTLR_RANGE0_Msk (0x1UL << ETM_TRCQCTLR_RANGE0_Pos) /*!< Bit mask of RANGE0 field.                            */
  #define ETM_TRCQCTLR_RANGE0_Min (0x0UL)            /*!< Min enumerator value of RANGE0 field.                                */
  #define ETM_TRCQCTLR_RANGE0_Max (0x1UL)            /*!< Max enumerator value of RANGE0 field.                                */
  #define ETM_TRCQCTLR_RANGE0_Disabled (0x0UL)       /*!< Address range comparator 0 is disabled.                              */
  #define ETM_TRCQCTLR_RANGE0_Enabled (0x1UL)        /*!< Address range comparator 0 is selected for use.                      */

/* RANGE1 @Bit 1 : Specifies the address range comparators to be used for controlling Q elements. */
  #define ETM_TRCQCTLR_RANGE1_Pos (1UL)              /*!< Position of RANGE1 field.                                            */
  #define ETM_TRCQCTLR_RANGE1_Msk (0x1UL << ETM_TRCQCTLR_RANGE1_Pos) /*!< Bit mask of RANGE1 field.                            */
  #define ETM_TRCQCTLR_RANGE1_Min (0x0UL)            /*!< Min enumerator value of RANGE1 field.                                */
  #define ETM_TRCQCTLR_RANGE1_Max (0x1UL)            /*!< Max enumerator value of RANGE1 field.                                */
  #define ETM_TRCQCTLR_RANGE1_Disabled (0x0UL)       /*!< Address range comparator 1 is disabled.                              */
  #define ETM_TRCQCTLR_RANGE1_Enabled (0x1UL)        /*!< Address range comparator 1 is selected for use.                      */

/* RANGE2 @Bit 2 : Specifies the address range comparators to be used for controlling Q elements. */
  #define ETM_TRCQCTLR_RANGE2_Pos (2UL)              /*!< Position of RANGE2 field.                                            */
  #define ETM_TRCQCTLR_RANGE2_Msk (0x1UL << ETM_TRCQCTLR_RANGE2_Pos) /*!< Bit mask of RANGE2 field.                            */
  #define ETM_TRCQCTLR_RANGE2_Min (0x0UL)            /*!< Min enumerator value of RANGE2 field.                                */
  #define ETM_TRCQCTLR_RANGE2_Max (0x1UL)            /*!< Max enumerator value of RANGE2 field.                                */
  #define ETM_TRCQCTLR_RANGE2_Disabled (0x0UL)       /*!< Address range comparator 2 is disabled.                              */
  #define ETM_TRCQCTLR_RANGE2_Enabled (0x1UL)        /*!< Address range comparator 2 is selected for use.                      */

/* RANGE3 @Bit 3 : Specifies the address range comparators to be used for controlling Q elements. */
  #define ETM_TRCQCTLR_RANGE3_Pos (3UL)              /*!< Position of RANGE3 field.                                            */
  #define ETM_TRCQCTLR_RANGE3_Msk (0x1UL << ETM_TRCQCTLR_RANGE3_Pos) /*!< Bit mask of RANGE3 field.                            */
  #define ETM_TRCQCTLR_RANGE3_Min (0x0UL)            /*!< Min enumerator value of RANGE3 field.                                */
  #define ETM_TRCQCTLR_RANGE3_Max (0x1UL)            /*!< Max enumerator value of RANGE3 field.                                */
  #define ETM_TRCQCTLR_RANGE3_Disabled (0x0UL)       /*!< Address range comparator 3 is disabled.                              */
  #define ETM_TRCQCTLR_RANGE3_Enabled (0x1UL)        /*!< Address range comparator 3 is selected for use.                      */

/* RANGE4 @Bit 4 : Specifies the address range comparators to be used for controlling Q elements. */
