  #define ETM_TRCSSCCR0_RST_Msk (0x1UL << ETM_TRCSSCCR0_RST_Pos) /*!< Bit mask of RST field.                                   */
  #define ETM_TRCSSCCR0_RST_Min (0x0UL)              /*!< Min enumerator value of RST field.                                   */
  #define ETM_TRCSSCCR0_RST_Max (0x1UL)              /*!< Max enumerator value of RST field.                                   */
  #define ETM_TRCSSCCR0_RST_Disabled (0x0UL)         /*!< Multiple matches can not be detected.                                */
  #define ETM_TRCSSCCR0_RST_Enabled (0x1UL)          /*!< Multiple matches can occur.                                          */


/* ETM_TRCSSCSR0: Indicates the status of the single-shot comparators. TRCSSCSR0 is sensitive toinstruction addresses. */
  #define ETM_TRCSSCSR0_ResetValue (0x00000000UL)    /*!< Reset value of TRCSSCSR0 register.                                   */

/* INST @Bit 0 : Instruction address comparator support */
