  #define RADIO_DFECTRL2_TSAMPLEOFFSET_Msk (0xFFFUL << RADIO_DFECTRL2_TSAMPLEOFFSET_Pos) /*!< Bit mask of TSAMPLEOFFSET field. */


/* RADIO_DFECTRL3: Various hacker/tuning configuration for Direction finding */
  #define RADIO_DFECTRL3_ResetValue (0x28433000UL)   /*!< Reset value of DFECTRL3 register.                                    */

