  #define RADIO_DFECTRL3_TREFPERIOD_Pos (24UL)       /*!< Position of TREFPERIOD field.                                        */
  #define RADIO_DFECTRL3_TREFPERIOD_Msk (0x1FUL << RADIO_DFECTRL3_TREFPERIOD_Pos) /*!< Bit mask of TREFPERIOD field.           */

