  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMDEFAULT_Pos (0UL) /*!< Position of LDOTRIMDEFAULT field.                 */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMDEFAULT_Msk (0xFUL << REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMDEFAULT_Pos)
                                                                            /*!< Bit mask of LDOTRIMDEFAULT field.*/

/* LDOTRIMHELPERELV @Bits 4..7 : Calibration of LDO reference voltage for ELV helper mode operation, 2nd complement */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERELV_Pos (4UL) /*!< Position of LDOTRIMHELPERELV field.             */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERELV_Msk (0xFUL << REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERELV_Pos)
                                                                            /*!< Bit mask of LDOTRIMHELPERELV field.*/

/* LDOTRIMHELPERPFM @Bits 8..11 : Calibration of LDO reference voltage for PFM helper mode operation, 2nd complement */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERPFM_Pos (8UL) /*!< Position of LDOTRIMHELPERPFM field.             */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERPFM_Msk (0xFUL << REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERPFM_Pos)
                                                                            /*!< Bit mask of LDOTRIMHELPERPFM field.*/

/* LDOTRIMHELPERPWM @Bits 12..15 : Calibration of LDO reference voltage for PWM helper mode operation, 2nd complement */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERPWM_Pos (12UL) /*!< Position of LDOTRIMHELPERPWM field.            */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERPWM_Msk (0xFUL << REGULATORS_VREGMAIN_CALIBRATION_CAL2_LDOTRIMHELPERPWM_Pos)
                                                                            /*!< Bit mask of LDOTRIMHELPERPWM field.*/

/* PFMVOLTCAL @Bits 16..20 : Calibration of BUCK_LP_PFM output voltage */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_PFMVOLTCAL_Pos (16UL) /*!< Position of PFMVOLTCAL field.                        */
  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_PFMVOLTCAL_Msk (0x1FUL << REGULATORS_VREGMAIN_CALIBRATION_CAL2_PFMVOLTCAL_Pos)
