  #define REGULATORS_VREGMAIN_CALIBRATION_CAL2_PFMELVVOLTCAL_Msk (0xFUL << REGULATORS_VREGMAIN_CALIBRATION_CAL2_PFMELVVOLTCAL_Pos)
